                player.judge(function (card) {
                    switch (card.suit) {
                        case 'spade':
                            return 2;
                        case 'heart':
                            return 1;
                        case 'club':
                            return 0;
                        case 'diamond':
                            return 0;
                    }
                });
                ('step 1');
                event.playersuit = result.suit;
                target.judge(function (card) {
                    switch (card.suit) {
                        case 'spade':
                            return 2;
                        case 'heart':
                            return 1;
                        case 'club':
                            return 0;
                        case 'diamond':
                            return 0;
                    }
                });
                ('step 2');
                event.targetsuit = result.suit;
                let mes = event.playersuit;
                const tes = event.targetsuit;
                let str;
