            lib.element.content.chooseToDoushou = function () {
                'step 0';
                let name = ['dsq_mao', 'dsq_xiang', 'dsq_shu', 'dsq_shi'];
                for (let i = 0; i < name.length; i++) {
                    if (!lib.card[name[i]]) {
                        lib.card[name[i]] = get.copy(lib.skill.equiplib[name[i]]);
                        lib.translate[name[i]] = get.translation(name[i]);
                        lib.translate[name[i] + '_info'] = get.translation(name[i] + '_info');
                    }
                }
                game.log(player, '对', target, '发起了', '#y斗兽');
                if (_status.connectMode) {
                    player
                        .chooseButtonOL(
                            [
                                [
                                    player,
                                    [
                                        '斗兽:请选择一颗斗兽棋',
                                        [
                                            [
                                                ['', '', 'dsq_mao'],
                                                ['', '', 'dsq_xiang'],
                                            ],
                                            'vcard',
                                        ],
                                    ],
                                    true,
                                ],
                                [
                                    target,
                                    [
                                        '斗兽:请选择一颗斗兽棋',
                                        [
                                            [
                                                ['', '', 'dsq_shu'],
                                                ['', '', 'dsq_shi'],
                                            ],
                                            'vcard',
                                        ],
                                    ],
                                    true,
                                ],
                            ],
                            function () { },
                            function () {
                                return 1 + Math.random();
                            },
                        )
                        .set('switchToAuto', function () {
                            _status.event.result = 'ai';
                        })
                        .set('processAI', function () {
                            const buttons = _status.event.dialog.buttons;
                            return {
                                bool: true,
                                links: [buttons.randomGet().link],
                            };
                        });
                }
                ('step 1');
                if (_status.connectMode) {
                    event.mes = result[player.playerid].links[0][2];
                    event.tes = result[target.playerid].links[0][2];
                    event.goto(4);
                } else {
                    player.chooseButton(
                        [
                            '斗兽:请选择一颗斗兽棋',
                            [
                                [
                                    ['', '', 'dsq_mao'],
                                    ['', '', 'dsq_xiang'],
                                ],
                                'vcard',
                            ],
                        ],
                        true,
                    ).ai = function () {
                        return 1 + Math.random();
                    };
                }
                ('step 2');
                event.mes = result.links[0][2];
                target.chooseButton(
                    [
                        '斗兽:请选择一颗斗兽棋',
                        [
                            [
                                ['', '', 'dsq_shu'],
                                ['', '', 'dsq_shi'],
                            ],
                            'vcard',
                        ],
                    ],
                    true,
                ).ai = function () {
                    return 1 + Math.random();
                };
                ('step 3');
                event.tes = result.links[0][2];
                ('step 4');
                game.broadcast(function () {
                    ui.arena.classList.add('thrownhighlight');
                });
                ui.arena.classList.add('thrownhighlight');
                game.addVideo('thrownhighlight1');
                player.$compare(game.createCard(event.mes, '', ''), target, game.createCard(event.tes, '', ''));
                game.log(player, '选择的斗兽棋为', '#g' + get.translation(event.mes + '1'));
                game.log(target, '选择的斗兽棋为', '#g' + get.translation(event.tes + '1'));
                ('step 5');
                let mes = event.mes;
                const tes = event.tes;
                let str;
                if ((mes == 'dsq_mao' && tes == 'dsq_shu') || (mes == 'dsq_xiang' && tes == 'dsq_shi')) {
                    str = get.translation(player) + '斗兽获胜';
                    player.popup('胜', 'wood');
                    target.popup('负', 'fire');
                    if (mes == 'dsq_mao') {
                        game.log('#g鼠', '成为了', '#g猫', '的盘中餐<br>', player, '#g胜');
                    } else {
                        game.log('#g象', '以身躯碾压', '#g狮<br>', player, '#g胜');
                    }
                    event.result = { bool: true };
                } else {
                    str = get.translation(target) + '斗兽获胜';
                    target.popup('胜', 'wood');
                    player.popup('负', 'fire');
                    if (tes == 'dsq_shu') {
                        game.log('#g鼠', '钻进了', '#g象', '的鼻子<br>', target, '#g胜');
                    } else {
                        game.log('#g狮', '把', '#g猫', '当作溜溜球玩<br>', target, '#g胜');
                    }
                    event.result = { bool: false };
                }
                game.broadcastAll(function (str) {
                    const dialog = ui.create.dialog(str);
                    dialog.classList.add('center');
                    setTimeout(function () {
                        dialog.close();
                    }, 1000);
                }, str);
                ('step 6');
                game.broadcastAll(function () {
                    ui.arena.classList.remove('thrownhighlight');
                });
                game.addVideo('thrownhighlight2');
                if (event.clear !== false) {
                    game.broadcastAll(ui.clear);
                }
            };
